import { withFirstModule } from "../internal-utils/module-utils.mjs";
import { ManualRunner } from "./runners/manual.mjs";
import { WebExtRunner } from "./runners/web-ext.mjs";
//#region src/internal/detect-runner.ts
async function detectRunner(config) {
	return withFirstModule(async () => {
		return new WebExtRunner(await import("web-ext").then((mod) => mod.default), await import("web-ext/util/logger"), config);
	}, () => new ManualRunner(config));
}
//#endregion
export { detectRunner };
